.app {
  max-width: 720px;
  margin: 0 REDACTED;
  padding: 32px 20px 64px;
}

.app__header {
  text-align: center;
  margin-bottom: 32px;
}

.app__header h1 {
  margin: 0 0 8px;
  font-size: 28px;
}

.app__header p {
  margin: 0;
  color: #6b7280;
  font-size: 14px;
}

